import { Effect, Metric } from "effect";
// What `app/docs/search` counts and logs (docs/features/docs.md#observability): one count and one log line per search
// its steps settle, by who asked (`door`: the agent's call or a person's), outcome, and how many pages it found and
// showed. Never the repository's docs' words: no query, path, URL, title or text.
/** Searches `app/docs/search` settled, by `door` and `outcome`. */
export const searches = Metric.counter("smithers_web_docs_searches", {
    description: "Searches of a repository's docs app/docs/search settled, by door and outcome",
    incremental: true,
});
/** Docs pages `app/docs/search` showed in the conversation, by `door`. */
export const shown = Metric.counter("smithers_web_docs_shown", {
    description: "Docs pages app/docs/search showed in the conversation, by door",
    incremental: true,
});
